package net.civeira.phylax.feature.template.templateversion.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.template.templateversion.domain.TemplateVersion;
import net.civeira.phylax.feature.template.templateversion.domain.valueobject.ContentHtmlVO;

class ContentHtmlValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of content html of template version")
  void test_content_html_value_holder_assign_plain_value() {
    Object holder = new Object();
    ContentHtmlValueHolder<Object> value = new ContentHtmlValueHolder<>(holder);
    Assertions.assertSame(holder, value.contentHtml("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getContentHtmlValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getContentHtml().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of content html of template version")
  void test_content_html_value_holder_assign_value_object() {
    Object holder = new Object();
    ContentHtmlValueHolder<Object> value = new ContentHtmlValueHolder<>(holder);
    ContentHtmlVO vo = ContentHtmlVO.from("one");
    Assertions.assertFalse(value.getContentHtmlValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.contentHtml(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getContentHtmlValue().orElseThrow());
    Assertions.assertSame(holder, value.contentHtml(Optional.empty()));
    Assertions.assertFalse(value.getContentHtmlValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.contentHtml(Optional.of(vo)));
    Assertions.assertSame(vo, value.getContentHtmlValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of content html of template version against the original")
  void test_content_html_value_holder_read() {
    Object holder = new Object();
    ContentHtmlValueHolder<Object> value = new ContentHtmlValueHolder<>(holder);
    ContentHtmlVO vo = ContentHtmlVO.from("one");
    ContentHtmlVO other = ContentHtmlVO.from("one");
    TemplateVersion original = Mockito.mock(TemplateVersion.class);
    Mockito.when(original.getContentHtmlValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readContentHtml(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readContentHtml(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.contentHtml(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readContentHtml(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readContentHtml(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of content html of template version")
  void test_content_html_value_holder_unset() {
    Object holder = new Object();
    ContentHtmlValueHolder<Object> value = new ContentHtmlValueHolder<>(holder);
    ContentHtmlVO vo = ContentHtmlVO.from("one");
    value.contentHtml(vo);
    Assertions.assertSame(holder, value.unsetContentHtmlIfMatches("contentHtml_other"));
    Assertions.assertTrue(value.getContentHtmlValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetContentHtmlIfMatches("contentHtml"));
    Assertions.assertFalse(value.getContentHtmlValue().isPresent(),
        "The field name must clear the value");
    value.contentHtml(vo);
    Assertions.assertSame(holder, value.unsetContentHtml());
    Assertions.assertFalse(value.getContentHtmlValue().isPresent(), "Unset must clear the value");
  }
}
